"use strict";(self.webpackChunklogbook=self.webpackChunklogbook||[]).push([[8301],{5761:(n,a,s)=>{s.r(a),s.d(a,{comp:()=>p,data:()=>c});var e=s(362);const t={},p=(0,s(5726).A)(t,[["render",function(n,a){return(0,e.uX)(),(0,e.CE)("div",null,[...a[0]||(a[0]=[(0,e.Fv)('<h1 id="浏览器缓存类型详解" tabindex="-1"><a class="header-anchor" href="#浏览器缓存类型详解"><span>浏览器缓存类型详解</span></a></h1><h2 id="http-缓存" tabindex="-1"><a class="header-anchor" href="#http-缓存"><span>HTTP 缓存</span></a></h2><h3 id="强缓存-strong-cache" tabindex="-1"><a class="header-anchor" href="#强缓存-strong-cache"><span>强缓存（Strong Cache）</span></a></h3><p>强缓存是指浏览器直接从本地缓存中获取资源，不发送 HTTP 请求到服务器。</p><h4 id="控制字段" tabindex="-1"><a class="header-anchor" href="#控制字段"><span>控制字段</span></a></h4><p><strong>Cache-Control</strong></p><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line"><span class="token header"><span class="token header-name keyword">Cache-Control</span><span class="token punctuation">:</span> <span class="token header-value">max-age=3600        # 缓存3600秒</span></span></span>\n<span class="line"><span class="token header"><span class="token header-name keyword">Cache-Control</span><span class="token punctuation">:</span> <span class="token header-value">no-cache            # 需要验证缓存</span></span></span>\n<span class="line"><span class="token header"><span class="token header-name keyword">Cache-Control</span><span class="token punctuation">:</span> <span class="token header-value">no-store            # 不缓存</span></span></span>\n<span class="line"><span class="token header"><span class="token header-name keyword">Cache-Control</span><span class="token punctuation">:</span> <span class="token header-value">private             # 仅客户端缓存</span></span></span>\n<span class="line"><span class="token header"><span class="token header-name keyword">Cache-Control</span><span class="token punctuation">:</span> <span class="token header-value">public              # 可被代理服务器缓存</span></span></span>\n<span class="line"><span class="token header"><span class="token header-name keyword">Cache-Control</span><span class="token punctuation">:</span> <span class="token header-value">immutable           # 资源永不变更</span></span></span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Expires</strong></p><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line"><span class="token header"><span class="token header-name keyword">Expires</span><span class="token punctuation">:</span> <span class="token header-value">Wed, 21 Oct 2024 07:28:00 GMT</span></span></span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="优先级" tabindex="-1"><a class="header-anchor" href="#优先级"><span>优先级</span></a></h4><ul><li><code>Cache-Control</code> &gt; <code>Expires</code></li><li><code>Cache-Control: no-cache</code> 会忽略 <code>Expires</code></li></ul><h3 id="协商缓存-negotiated-cache" tabindex="-1"><a class="header-anchor" href="#协商缓存-negotiated-cache"><span>协商缓存（Negotiated Cache）</span></a></h3><p>协商缓存需要浏览器发送请求到服务器，服务器判断资源是否更新。</p><h4 id="etag-机制" tabindex="-1"><a class="header-anchor" href="#etag-机制"><span>ETag 机制</span></a></h4><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line"># 请求头</span>\n<span class="line"><span class="token header"><span class="token header-name keyword">If-None-Match</span><span class="token punctuation">:</span> <span class="token header-value">&quot;abc123&quot;</span></span></span>\n<span class="line"></span>\n<span class="line"># 响应头</span>\n<span class="line"><span class="token header"><span class="token header-name keyword">ETag</span><span class="token punctuation">:</span> <span class="token header-value">&quot;abc123&quot;</span></span></span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="last-modified-机制" tabindex="-1"><a class="header-anchor" href="#last-modified-机制"><span>Last-Modified 机制</span></a></h4><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line"># 请求头</span>\n<span class="line"><span class="token header"><span class="token header-name keyword">If-Modified-Since</span><span class="token punctuation">:</span> <span class="token header-value">Wed, 21 Oct 2024 07:28:00 GMT</span></span></span>\n<span class="line"></span>\n<span class="line"># 响应头</span>\n<span class="line"><span class="token header"><span class="token header-name keyword">Last-Modified</span><span class="token punctuation">:</span> <span class="token header-value">Wed, 21 Oct 2024 07:28:00 GMT</span></span></span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="响应状态码" tabindex="-1"><a class="header-anchor" href="#响应状态码"><span>响应状态码</span></a></h4><ul><li><code>200 OK</code>：资源已更新，返回新内容</li><li><code>304 Not Modified</code>：资源未更新，使用缓存</li></ul><h2 id="浏览器缓存层级" tabindex="-1"><a class="header-anchor" href="#浏览器缓存层级"><span>浏览器缓存层级</span></a></h2><h3 id="memory-cache-内存缓存" tabindex="-1"><a class="header-anchor" href="#memory-cache-内存缓存"><span>Memory Cache（内存缓存）</span></a></h3><ul><li><strong>位置</strong>：浏览器内存</li><li><strong>特点</strong>：速度最快，容量有限</li><li><strong>生命周期</strong>：页面关闭时清除</li><li><strong>适用</strong>：CSS、JS、图片等静态资源</li></ul><h3 id="disk-cache-磁盘缓存" tabindex="-1"><a class="header-anchor" href="#disk-cache-磁盘缓存"><span>Disk Cache（磁盘缓存）</span></a></h3><ul><li><strong>位置</strong>：硬盘存储</li><li><strong>特点</strong>：容量大，速度较慢</li><li><strong>生命周期</strong>：持久化存储</li><li><strong>适用</strong>：大文件、长期缓存资源</li></ul><h3 id="http-cache-http-缓存" tabindex="-1"><a class="header-anchor" href="#http-cache-http-缓存"><span>HTTP Cache（HTTP 缓存）</span></a></h3><ul><li><strong>位置</strong>：浏览器缓存系统</li><li><strong>特点</strong>：遵循 HTTP 缓存规则</li><li><strong>生命周期</strong>：根据 HTTP 头部控制</li><li><strong>适用</strong>：所有 HTTP 资源</li></ul><h2 id="应用缓存" tabindex="-1"><a class="header-anchor" href="#应用缓存"><span>应用缓存</span></a></h2><h3 id="service-worker-缓存" tabindex="-1"><a class="header-anchor" href="#service-worker-缓存"><span>Service Worker 缓存</span></a></h3><p>现代浏览器的离线缓存方案，提供更精细的缓存控制。</p><h4 id="缓存策略" tabindex="-1"><a class="header-anchor" href="#缓存策略"><span>缓存策略</span></a></h4><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// Cache First策略</span></span>\n<span class="line">self<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&quot;fetch&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>\n<span class="line">  event<span class="token punctuation">.</span><span class="token function">respondWith</span><span class="token punctuation">(</span></span>\n<span class="line">    caches<span class="token punctuation">.</span><span class="token function">match</span><span class="token punctuation">(</span>event<span class="token punctuation">.</span>request<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">response</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>\n<span class="line">      <span class="token keyword">return</span> response <span class="token operator">||</span> <span class="token function">fetch</span><span class="token punctuation">(</span>event<span class="token punctuation">.</span>request<span class="token punctuation">)</span><span class="token punctuation">;</span></span>\n<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span></span>\n<span class="line">  <span class="token punctuation">)</span><span class="token punctuation">;</span></span>\n<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>\n<span class="line"></span>\n<span class="line"><span class="token comment">// Network First策略</span></span>\n<span class="line">self<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&quot;fetch&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>\n<span class="line">  event<span class="token punctuation">.</span><span class="token function">respondWith</span><span class="token punctuation">(</span></span>\n<span class="line">    <span class="token function">fetch</span><span class="token punctuation">(</span>event<span class="token punctuation">.</span>request<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> caches<span class="token punctuation">.</span><span class="token function">match</span><span class="token punctuation">(</span>event<span class="token punctuation">.</span>request<span class="token punctuation">)</span><span class="token punctuation">)</span></span>\n<span class="line">  <span class="token punctuation">)</span><span class="token punctuation">;</span></span>\n<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>\n<span class="line"></span>\n<span class="line"><span class="token comment">// Stale While Revalidate策略</span></span>\n<span class="line">self<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&quot;fetch&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>\n<span class="line">  event<span class="token punctuation">.</span><span class="token function">respondWith</span><span class="token punctuation">(</span></span>\n<span class="line">    caches<span class="token punctuation">.</span><span class="token function">match</span><span class="token punctuation">(</span>event<span class="token punctuation">.</span>request<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">response</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>\n<span class="line">      <span class="token keyword">const</span> fetchPromise <span class="token operator">=</span> <span class="token function">fetch</span><span class="token punctuation">(</span>event<span class="token punctuation">.</span>request<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">networkResponse</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>\n<span class="line">        caches<span class="token punctuation">.</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token string">&quot;v1&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">cache</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>\n<span class="line">          cache<span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span>event<span class="token punctuation">.</span>request<span class="token punctuation">,</span> networkResponse<span class="token punctuation">.</span><span class="token function">clone</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>\n<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>\n<span class="line">        <span class="token keyword">return</span> networkResponse<span class="token punctuation">;</span></span>\n<span class="line">      <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>\n<span class="line">      <span class="token keyword">return</span> response <span class="token operator">||</span> fetchPromise<span class="token punctuation">;</span></span>\n<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span></span>\n<span class="line">  <span class="token punctuation">)</span><span class="token punctuation">;</span></span>\n<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="application-cache-已废弃" tabindex="-1"><a class="header-anchor" href="#application-cache-已废弃"><span>Application Cache（已废弃）</span></a></h3><p>HTML5 的离线缓存方案，已被 Service Worker 替代。</p><h2 id="缓存存储位置" tabindex="-1"><a class="header-anchor" href="#缓存存储位置"><span>缓存存储位置</span></a></h2><h3 id="chrome-浏览器" tabindex="-1"><a class="header-anchor" href="#chrome-浏览器"><span>Chrome 浏览器</span></a></h3><ul><li><strong>内存缓存</strong>：Chrome 进程内存</li><li><strong>磁盘缓存</strong>：<code>~/Library/Caches/Google/Chrome/Default/Cache/</code></li><li><strong>Service Worker</strong>：<code>~/Library/Application Support/Google/Chrome/Default/Service Worker/</code></li></ul><h3 id="firefox-浏览器" tabindex="-1"><a class="header-anchor" href="#firefox-浏览器"><span>Firefox 浏览器</span></a></h3><ul><li><strong>内存缓存</strong>：Firefox 进程内存</li><li><strong>磁盘缓存</strong>：<code>~/Library/Caches/Firefox/Profiles/[profile]/cache2/</code></li><li><strong>Service Worker</strong>：<code>~/Library/Application Support/Firefox/Profiles/[profile]/storage/</code></li></ul><h3 id="safari-浏览器" tabindex="-1"><a class="header-anchor" href="#safari-浏览器"><span>Safari 浏览器</span></a></h3><ul><li><strong>内存缓存</strong>：Safari 进程内存</li><li><strong>磁盘缓存</strong>：<code>~/Library/Caches/com.apple.Safari/</code></li><li><strong>Service Worker</strong>：<code>~/Library/WebKit/ServiceWorkers/</code></li></ul><h2 id="缓存优先级" tabindex="-1"><a class="header-anchor" href="#缓存优先级"><span>缓存优先级</span></a></h2><ol><li><strong>Service Worker 缓存</strong>（如果存在）</li><li><strong>Memory Cache</strong></li><li><strong>Disk Cache</strong></li><li><strong>网络请求</strong></li></ol><h2 id="缓存失效机制" tabindex="-1"><a class="header-anchor" href="#缓存失效机制"><span>缓存失效机制</span></a></h2><h3 id="自动失效" tabindex="-1"><a class="header-anchor" href="#自动失效"><span>自动失效</span></a></h3><ul><li>超过<code>max-age</code>时间</li><li>超过<code>Expires</code>时间</li><li>浏览器存储空间不足</li></ul><h3 id="手动失效" tabindex="-1"><a class="header-anchor" href="#手动失效"><span>手动失效</span></a></h3><ul><li>用户清除浏览器缓存</li><li>开发者工具中禁用缓存</li><li>强制刷新（Ctrl+F5）</li></ul><h3 id="版本控制失效" tabindex="-1"><a class="header-anchor" href="#版本控制失效"><span>版本控制失效</span></a></h3><ul><li>URL 参数变化（如<code>?v=1.0.1</code>）</li><li>文件名哈希变化（如<code>app.abc123.js</code>）</li><li>ETag 值变化</li></ul><h2 id="缓存大小限制" tabindex="-1"><a class="header-anchor" href="#缓存大小限制"><span>缓存大小限制</span></a></h2><h3 id="浏览器限制" tabindex="-1"><a class="header-anchor" href="#浏览器限制"><span>浏览器限制</span></a></h3><ul><li><strong>Chrome</strong>：约 80%可用磁盘空间</li><li><strong>Firefox</strong>：约 50%可用磁盘空间</li><li><strong>Safari</strong>：约 1GB</li></ul><h3 id="单个资源限制" tabindex="-1"><a class="header-anchor" href="#单个资源限制"><span>单个资源限制</span></a></h3><ul><li><strong>Memory Cache</strong>：通常几 MB</li><li><strong>Disk Cache</strong>：通常几 GB</li><li><strong>Service Worker</strong>：通常几 GB</li></ul><h2 id="跨域缓存" tabindex="-1"><a class="header-anchor" href="#跨域缓存"><span>跨域缓存</span></a></h2><h3 id="同源策略" tabindex="-1"><a class="header-anchor" href="#同源策略"><span>同源策略</span></a></h3><ul><li>缓存遵循同源策略</li><li>不同域的资源独立缓存</li><li>CORS 影响缓存行为</li></ul><h3 id="共享缓存" tabindex="-1"><a class="header-anchor" href="#共享缓存"><span>共享缓存</span></a></h3><ul><li>CDN 缓存可跨域共享</li><li>代理服务器缓存</li><li>浏览器厂商缓存优化</li></ul>',59)])])}]]),c=JSON.parse('{"path":"/cache/cache-types.html","title":"浏览器缓存类型详解","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1761186389000,"contributors":[{"name":"loopbin","username":"loopbin","email":"lzb100562@163.com","commits":1,"url":"https://github.com/loopbin"}],"changelog":[{"hash":"4638ac43c531aac6e15823223bb352dc58ce2135","time":1761186389000,"email":"lzb100562@163.com","author":"loopbin","message":"feat: 1"}]},"filePathRelative":"cache/cache-types.md"}')}}]);